package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.Delays;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Color;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.World;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Witch;
import org.bukkit.event.entity.ProjectileLaunchEvent;

public final class ThunderWizardBehaviour implements CompiledBehaviour {
    private static final Particle CAMPFIRE_COSY_SMOKE = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:campfire_cosy_smoke");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle INSTANT_EFFECT = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:instant_effect");

    private static final TimeUnit SECONDS = TimeUnit.SECONDS;

    private final MobContext context;

    private Cooldown cooldown;

    private Cooldown cooldown2;

    private Location variableMark;

    private Delays delays;

    public ThunderWizardBehaviour(MobContext context) {
        this.context = context;
        // node #17 function.cooldown
        this.cooldown = new Cooldown();
        // node #29 function.cooldown
        this.cooldown2 = new Cooldown();
        // node #32 variable.set
        this.variableMark = null;
        // node #38 flow.delay
        this.delays = new Delays();
    }

    @Override
    public void onNightEnd() {
        // node #6 mob.night_end
        // node #8 world.spawn_particle
        // node #7 mob.self
        final Witch self = ((Witch) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), CAMPFIRE_COSY_SMOKE, self.getEyeLocation(), 30, 1.5d, 1.0d, 1.5d, null);
        // node #9
    }

    @Override
    public void onProjectileShoot(ProjectileLaunchEvent event) {
        // node #13 event.projectile_shoot
        // node #14 cancellable.mutate
        event.setCancelled(true);
        // node #15
    }

    @Override
    public void onTick() {
        this.delays.tick();
        // node #45 mob.tick
        // node #49 flow.branch
        // node #46 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (cooldown) {
            // node #48 world.spawn_particle
            // node #47 mob.self
            final Witch self = ((Witch) this.context.entity());
            BukkitRuntime.particles(this.context, self.getWorld(), INSTANT_EFFECT, self.getEyeLocation(), 15, 1.5d, 1.0d, 1.5d, new Particle.Spell(Color.fromRGB(255, 255, 255), 1.0f));
        }
        // node #61 flow.branch
        // node #50 mob.self
        final Witch self = ((Witch) this.context.entity());
        // node #51 mob.read
        final LivingEntity target = self.getTarget();
        if (target == null) return;
        // node #60 flow.branch
        // node #52 function.cooldown
        final boolean cooldown2 = this.cooldown2.ready(MILLISECONDS.toMillis(4000.0d));
        if (!cooldown2) return;
        // node #59 flow.branch
        if (!(BukkitRuntime.hasLineOfSight(self, target))) return;
        // node #58 variable.set
        this.variableMark = target.getLocation();
        final Location set = this.variableMark;
        // node #54 world.strike_lightning
        // node #53 mob.read
        final World world = self.getWorld();
        BukkitRuntime.strikeLightning(this.context, world, set, true);
        // node #57 flow.delay
        this.delays.after(SECONDS.toMillis(1.5d), () -> {
            // node #56 world.strike_lightning
            // node #55 variable.get
            final Location variable = this.variableMark;
            BukkitRuntime.strikeLightning(this.context, world, variable, false);
        });
        // node #62
    }
}
